import { test } from 'node:test';
import assert from 'node:assert/strict';
import { SrpClient, N, N_BYTES, g, modPow, computeK, computeX, bigIntToBytes, bytesToBigInt } from '../lib/ente/srp.ts';
import { sha256 } from '@noble/hashes/sha2.js';

const enc = (s: string) => new TextEncoder().encode(s);
const hex = (b: Uint8Array) => Buffer.from(b).toString('hex');
const unhex = (s: string) => new Uint8Array(Buffer.from(s, 'hex'));

// Known-answer vector from ente-io/ente
// rust/crates/accounts/src/auth/srp.rs `test_known_vector_leading_zero_a_matches_go_server_m1`
// ("Generated by the Go server's github.com/ente/go-srp").
test('SRP M1 matches Ente Go server known-answer vector (leading-zero A)', () => {
  const srpUserID = 'repro-user-id';
  const salt = enc('0123456789abcdef');
  const loginKey = enc('1234567890abcdef');
  const aPrivate = unhex('00'.repeat(62) + '06de');
  const bPrivate = new Uint8Array(64).fill(0x42);

  // Server side, as the srp crate's ServerG4096: v = g^x, B = k*v + g^b mod N.
  const x = computeX(enc(srpUserID), loginKey, salt);
  const v = modPow(g, x, N);
  const B = (computeK() * v + modPow(g, bytesToBigInt(bPrivate), N)) % N;

  const client = new SrpClient(srpUserID, salt, loginKey, aPrivate);
  assert.equal(client.publicA().length, N_BYTES);
  assert.equal(client.publicA()[0], 0, 'vector exercises a leading-zero A');

  const m1 = client.computeM1(bigIntToBytes(B));
  assert.equal(hex(m1), 'c0953b8c74d400fbf664a515deb700d73b65231e7e207a2e2326ff8cf70567ac');
});

test('SRP M2 verification accepts the right proof and rejects a tampered one', () => {
  const salt = new Uint8Array(16).fill(0x22);
  const loginKey = new Uint8Array(16).fill(0x11);
  const x = computeX(enc('test-user-id'), loginKey, salt);
  const B = (computeK() * modPow(g, x, N) + modPow(g, 12345n, N)) % N;
  const client = new SrpClient('test-user-id', salt, loginKey, new Uint8Array(64).fill(0x44));
  const m1 = client.computeM1(bigIntToBytes(B));

  // Server-side S = (A * v^u)^b; both sides must agree on K.
  const A = bytesToBigInt(client.publicA());
  const pad = (n: bigint) => { const b = bigIntToBytes(n); const o = new Uint8Array(N_BYTES); o.set(b, N_BYTES - b.length); return o; };
  const u = bytesToBigInt(sha256(new Uint8Array([...pad(A), ...pad(B)])));
  const S = modPow(A * modPow(modPow(g, x, N), u, N), 12345n, N);
  const K = sha256(pad(S));
  const m2 = sha256(new Uint8Array([...pad(A), ...m1, ...K]));

  client.verifyM2(m2);
  m2[0]! ^= 1;
  assert.throws(() => client.verifyM2(m2));
});

test('SRP rejects malicious B and wrong login key size', () => {
  const client = new SrpClient('u', new Uint8Array(16), new Uint8Array(16));
  assert.throws(() => client.computeM1(bigIntToBytes(N)));
  assert.throws(() => client.computeM1(new Uint8Array(N_BYTES + 1).fill(1)));
  assert.throws(() => new SrpClient('u', new Uint8Array(16), new Uint8Array(32)));
});
